package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    attribute pressedDurationS : Real := 0.0;
    attribute running : Boolean := false;
    attribute previousPressed : Boolean := false;
    perform action tick {
      first start;
      then if io_0 and not previousPressed {
        first start;
        then assign running := true;
      }
      then if not io_0 and previousPressed {
        first start;
        then assign running := false;
        then assign pressedDurationS := 0.0;
      }
      then if running and io_0 {
        first start;
        then assign pressedDurationS := 0.0;
      }
      then assign previousPressed := io_0;
    }
    out attribute serial_0_trigger : Boolean = not running and previousPressed;
    out attribute serial_0_value_0 : Real = pressedDurationS;
  }
  part system : Controller;
}
